check:
{v:'VER',what:'graphics program gfx9: dynamic coloured lights: at night under LIGHTING HIGH an open extraction ring lights its centre teal (green over red at least 10 above CLASSIC), an orange blast flash lights its ground orange (red over blue at least 4 above CLASSIC), and the far ground is unchanged; read from the world canvas just before the fog of war sheet',
 run:function(){
   if(!(window.__gfxStage&&window.__frame&&window.__state&&window.__endRaid)||typeof gfxPreFog!=='function'||typeof render2D!=='function'||typeof ZOOM!=='function') return 'SKIP: this fixture cannot stage and draw a raid frame';
   var bad=[], g=null, p, keepPF=gfxPreFog, gl0=CFG.gfxLight, L0=null, E0=null, F0=null, z=null, i, j, cap=null, want=null, C, H, fz, dz, dfl, ff, inb0, bt0;
   function grab(){
     var out=[], q, s, d, n, r0, g0, b0, k, m, Zq=ZOOM(), dx, dy;
     for(q=0;q<want.length;q++){
       r0=0; g0=0; b0=0; n=0;
       for(k=0;k<want[q].length;k++){
         s=want[q][k]; dx=Math.round((s[0]-VX)*Zq*DPR); dy=Math.round((s[1]-VY)*Zq*DPR);
         if(dx<3||dy<3||dx>cv.width-4||dy>cv.height-4) continue;
         d=wc.getImageData(dx-2,dy-2,5,5).data;
         for(m=0;m<d.length;m+=4){ r0+=d[m]; g0+=d[m+1]; b0+=d[m+2]; n++; }
       }
       out.push(n?[r0/n,g0/n,b0/n]:null);
     }
     return out;
   }
   function shoot(q){
     CFG.gfxLight=q; cap=null;
     gfxPreFog=function(dt){ try{ cap=grab(); }catch(_g){ cap=null; } return keepPF(dt); };
     try{ __frame(0); } finally { gfxPreFog=keepPF; }
     return cap;
   }
   function pts(cx,cy){ return [[cx,cy],[cx+8,cy],[cx-8,cy],[cx,cy+8],[cx,cy-8]]; }
   try{
     __resetCfg();
     g=__gfxStage({cond:'night',wx:'clear',frames:3});
     if(!g) return 'SKIP: __gfxStage built no raid';
     if(isDay()) return 'SKIP: the staged raid is not at night';
     p=g.player; G.shake=0; G.lightning=0;
     for(i=0;i<(G.zones||[]).length;i++) if(G.zones[i]&&G.zones[i].open){ z=G.zones[i]; break; }
     if(!z) return 'SKIP: staging: no open extraction ring';
     inb0=G.beaconT; bt0=true; G.beaconT=null;
     L0=G.lights; E0=G.ents; F0=G.flashes; G.ents=[]; G.flashes=[]; G.lights=[];
     p.x=z.x+300; p.y=z.y; G.anchX=undefined;
     for(j=0;j<4;j++) __frame(0.12);
     ff={x:z.x+300,y:z.y-200};
     G.flashes=[{x:ff.x,y:ff.y,r:150,c:'#ff7a4a',t:0,life:.25}];
     want=[pts(z.x,z.y),pts(ff.x,ff.y+20),pts(z.x+300,z.y+260)];
     C=shoot(0); H=shoot(2);
     if(!(C&&H&&C[0]&&H[0]&&C[1]&&H[1])) return 'SKIP: staging: the ring or the flash left the screen';
     dz=(H[0][1]-H[0][0])-(C[0][1]-C[0][0]);
     if(!(dz>=10)) bad.push('under HIGH the open ring centre is only '+dz.toFixed(1)+' greener over red than CLASSIC (want 10 or more)');
     dfl=(H[1][0]-H[1][2])-(C[1][0]-C[1][2]);
     if(!(dfl>=4)) bad.push('under HIGH an orange blast lights its ground only '+dfl.toFixed(1)+' redder over blue than CLASSIC (want 4 or more)');
     if(C[2]&&H[2]){ fz=Math.abs((H[2][0]+H[2][1]+H[2][2])-(C[2][0]+C[2][1]+C[2][2]))/3; if(fz>3) bad.push('ground away from every light moved by '+fz.toFixed(1)); }
   }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
   finally{
     gfxPreFog=keepPF; CFG.gfxLight=gl0;
     try{ if(g&&G===g){ if(L0) G.lights=L0; if(E0) G.ents=E0; if(F0) G.flashes=F0; if(bt0) G.beaconT=inb0; } }catch(_r){}
     try{ var g2=__state(); if(g2&&!g2.over) __endRaid('abandon'); }catch(_e){}
     __topClear(); __cleanProfile();
   }
   return bad.length?bad.join('; '):null; }},
